INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('22-20261109', 'f8', 'requirement', 'GPA 3.0 standing', 'Maintain minimum overall GPA 3.0.', 'https://cse.ucsd.edu/graduate/degree-programs/ms-program', 'minimum overall GPA of 3.0 at UC San Diego.', '2026-11-06T22:44:50.552Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('22-20261109', 'f9', 'requirement', 'CSE 298 thesis units', '8–12 units CSE 298 for thesis plan.', 'https://cse.ucsd.edu/graduate/degree-programs/ms-program', 'minimum of eight and maximum of twelve units of CSE 298 (Independent Research) is required.', '2026-11-06T22:44:50.552Z');
