INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('22-20261109', 'f11', 'requirement', 'Preferred undergrad majors', 'CS/CE/EE/math preferred.', 'https://cse.ucsd.edu/graduate/admissions', 'bachelor''s degree in computer science, computer engineering, electrical engineering, or mathematics is preferred, but not required.', '2026-11-06T22:44:50.552Z');
