INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('22-20261109', 'f14', 'deadline', 'Fall 2027 application window', 'Sep 2–Dec 16, 2026 PST.', 'https://cse.ucsd.edu/graduate/admissions', 'opens for Fall 2027 admission from September 2, 2026 until December 16, 2026 at 11:59 p.m.  PST.', '2026-11-06T22:44:50.552Z');
