INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f300', 'overview', 'Program summary', 'Current (2026-2027) CSUF catalog page for Computer Science, M.S. (catoid=101, poid=47271) — the exact page our automated fetch is bot-blocked on; Achsah confirmed this content directly by saving the live page as a PDF from her own browser.', 'https://catalog.fullerton.edu/preview_program.php?catoid=101&poid=47271', 'The Master of Science in Computer Science program emphasizes the study of advanced computational theory and practice to prepare students for successful careers in computer science.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f301', 'requirement', 'Admission GPA — CS/engineering, domestic', 'Current (2026-2027) CSUF catalog page for Computer Science, M.S. (catoid=101, poid=47271) — the exact page our automated fetch is bot-blocked on; Achsah confirmed this content directly by saving the live page as a PDF from her own browser.', 'https://catalog.fullerton.edu/preview_program.php?catoid=101&poid=47271', 'Minimum GPA of 2.5 for applicants graduated from domestic (U.S.) institutions with undergraduate degrees in engineering or computer science.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261109', 'f302', 'requirement', 'Admission GPA — CS/engineering, ABET international', 'Current (2026-2027) CSUF catalog page for Computer Science, M.S. (catoid=101, poid=47271) — the exact page our automated fetch is bot-blocked on; Achsah confirmed this content directly by saving the live page as a PDF from her own browser.', 'https://catalog.fullerton.edu/preview_program.php?catoid=101&poid=47271', 'Minimum GPA of 2.5 for applicants graduated from ABET-accredited international institutions with undergraduate degrees in engineering or computer science.', '2026-11-08T21:51:46.613Z');
